const b=$('05.01 - Load Active Accounts for Catalog Sync').item.json;
const row=$json;
const val=(...names)=>{for(const n of names){if(row[n]!==undefined&&row[n]!==null&&String(row[n]).trim()!=='')return row[n];}return '';};
const cleanNum=(v)=>{if(v===null||v===undefined||v==='')return null;const s=String(v).replace(/[৳,\s]/g,'');const n=Number(s);return Number.isFinite(n)?n:null;};
const name=String(val('Product Name','Name','Product')).trim(); if(!name)return[];
let category=String(val('Category')).trim(); const desc=String(val('Product Description','Description')).trim();
if(!category){const s=(name+' '+desc).toLowerCase();if(/শাড়ি|শাড়ি|saree|sari/.test(s))category='Saree';else if(/shirt|t-shirt|পাঞ্জাবি|panjabi/.test(s))category='Clothing';else category='Uncategorized';}
const price=cleanNum(val('Price','Price (৳)','Price(৳)','মূল্য'));
const stockStatus=String(val('Stock Status','Stock')).trim();
const stockQty=cleanNum(val('Stock Qty','Quantity','Qty'));
const imageUrl=String(val('Product Image','Image','Image URL','Photo')).trim();
const productUrl=String(val('Product URL','Product Link','URL','Link')).trim();
const externalProductId=String(val('Product ID','SKU','ID')).trim() || (name.toLowerCase().replace(/[^\p{L}\p{N}]+/gu,'-').replace(/^-|-$/g,'').slice(0,80)+'-'+String(price??'na'));
const aliases=String(val('Aliases')).trim();
const searchText=[name,category,desc,aliases].filter(Boolean).join(' ').toLowerCase();
const contentHash=Buffer.from(JSON.stringify({name,category,price,stockStatus,stockQty,desc,imageUrl,productUrl,aliases})).toString('base64').slice(0,180);
return [{json:{businessId:b.business_id,accountId:b.account_id,externalProductId,name,category,subcategory:String(val('Subcategory')).trim(),price,currency:String(val('Currency')).trim()||'BDT',stockQty,stockStatus,color:String(val('Color')).trim(),size:String(val('Size')).trim(),description:desc,imageUrl,offer:String(val('Offer')).trim(),discount:String(val('Discount')).trim(),aliases,searchText,contentHash,raw:row}}];

